class Solution:
    def maximumStrongPairXor(self, nums: List[int]) -> int:
        max_xor = 0
        n = len(nums)
        for i in range(n):
            for j in range(n):
                a = nums[i]
                b = nums[j]
                if max(a, b) <= 2 * min(a, b):
                    current = a ^ b
                    if current > max_xor:
                        max_xor = current
        return max_xor
